// High-level summary across all planned stages including aggregate
// metrics, critical-path identification, resource allocation patterns,
// budget distribution, schedule analytics, quality targets, risk
// profile, and plan health. Draws from PMBOK phase-gate discipline,
// SAFe PI planning cadence, PRINCE2 stage boundary management, and
// TOGAF architecture road-mapping.
type StageOverview struct {
	som.SomNode
}

// NewStageOverview binds a StageOverview facade to a document and a path.
func NewStageOverview(doc *som.SpecDocument, path string) *StageOverview {
	return &StageOverview{SomNode: som.NewSomNode(doc, path)}
}

func (x *StageOverview) Content() *StageOverviewContentForm {
	return NewStageOverviewContentForm(x.Doc(), x.Path()+"/content")
}

// Summary metrics across all stages.
func (x *StageOverview) Metrics() *StageOverviewMetrics {
	return NewStageOverviewMetrics(x.Doc(), x.Path()+"/metrics")
}

